# ==========================================
# CLI tools for Bash: fzf, ripgrep, fd, bat, zoxide (sourced from ~/.bashrc, hook added by setup.sh)
# ==========================================
# Colors: fzf reads ~/.cache/theme/fzf.opts (generated by apply-theme.sh) on every run;
# bat and ripgrep use ANSI color names, which Kitty maps to the Color Engine palette.
# Debian names the binaries fdfind/batcat: setup.sh links them as fd/bat in ~/.local/bin.

CE_CLI_DIR="$HOME/dotfiles/cli"

# --- bat: syntax-highlighted cat & pager (also for man pages) ---
if command -v bat >/dev/null 2>&1; then
    export BAT_CONFIG_PATH="$CE_CLI_DIR/bat.conf"
    export MANPAGER="sh -c 'col -bx | bat --language=man --plain'"
    export MANROFFOPT="-c"
fi

# --- ripgrep: smart case, hidden files, Color Engine colors ---
command -v rg >/dev/null 2>&1 && export RIPGREP_CONFIG_PATH="$CE_CLI_DIR/ripgreprc"

# --- fzf: Ctrl+T files, Alt+C folders, Ctrl+R history (all with previews) ---
if command -v fzf >/dev/null 2>&1; then
    export FZF_DEFAULT_OPTS_FILE="$HOME/.cache/theme/fzf.opts"
    if command -v fd >/dev/null 2>&1; then
        export FZF_DEFAULT_COMMAND="fd --type f --hidden --follow --exclude .git"
        export FZF_CTRL_T_COMMAND="fd --hidden --follow --exclude .git"
        export FZF_ALT_C_COMMAND="fd --type d --hidden --follow --exclude .git"
    fi
    export FZF_CTRL_T_OPTS="--border-label=' files ' --preview 'if [ -d {} ]; then ls -A --color=always --group-directories-first {}; else bat --color=always --style=numbers --line-range=:300 {}; fi'"
    export FZF_ALT_C_OPTS="--border-label=' jump to folder ' --preview 'ls -A --color=always --group-directories-first {}'"
    export FZF_CTRL_R_OPTS="--border-label=' history ' --no-preview"
    eval "$(fzf --bash)"

    # fif [text]: live "find in files". Type to search with ripgrep, preview the hit with bat,
    # Enter opens the file in Neovim on that line.
    fif() {
        local rg_cmd="rg --column --line-number --no-heading --color=always" hit file line
        hit=$(fzf --ansi --disabled --query "$*" \
                --bind "start:reload:$rg_cmd -- {q} || true" \
                --bind "change:reload:sleep 0.1; $rg_cmd -- {q} || true" \
                --delimiter : --border-label ' find in files ' \
                --preview 'bat --color=always --style=numbers --highlight-line {2} {1}' \
                --preview-window 'up,60%,+{2}+3/3,~3') || return
        IFS=: read -r file line _ <<< "$hit"
        "${EDITOR:-nvim}" "+$line" "$file"
    }
fi

# --- zoxide: 'z <part of a path>' jumps to a frequently used folder, 'zi' picks one with fzf ---
# (initialized last, as zoxide recommends)
command -v zoxide >/dev/null 2>&1 && eval "$(zoxide init bash)"

unset CE_CLI_DIR
